import os
import sys

print("CWD:", os.getcwd())
for root, dirs, files in os.walk("."):
    # skip hidden dirs like .codex to keep output small
    dirs[:] = [d for d in dirs if not d.startswith(".")]
    for f in files:
        p = os.path.join(root, f)
        print(p, os.path.getsize(p))

# Try to read report.pdf page count
try:
    from pypdf import PdfReader
except ImportError:
    try:
        from PyPDF2 import PdfReader
    except ImportError:
        print("No pypdf/PyPDF2 available")
        sys.exit(0)

for candidate in ["report.pdf", os.path.join(".", "report.pdf")]:
    if os.path.exists(candidate):
        reader = PdfReader(candidate)
        print("PDF:", candidate, "pages:", len(reader.pages))
        meta = reader.metadata
        print("Metadata:", meta)
        break
else:
    print("report.pdf not found in workspace")

import importlib

for mod in ["pypdf", "PyPDF2", "pdfplumber", "reportlab", "fitz", "pikepdf", "pdfrw"]:
    try:
        importlib.import_module(mod)
        print(mod, "AVAILABLE")
    except Exception as e:
        print(mod, "unavailable:", type(e).__name__, str(e)[:80])

